    def _collect_free_mode_session_snapshot(self) -> dict:
        run_dir_value = ""
        selected_ann = self._get_preview_annotation()
        input_dir_value = str(self.input_dir_var.get() or "").strip()
        if (
            self._normalize_workflow_route_value() == "manual"
            and self._normalize_manual_entry_mode() == "new"
            and not self._manual_review_active
            and not self._manual_review_from_auto
            and not self.is_processing
        ):
            input_dir_value = ""

        for candidate in (
            getattr(self, "current_annotation_run_dir", None),
            getattr(self, "last_staging_run_dir", None),
            str(self.plate_dataset_run_var.get() or "").strip(),
        ):
            safe_run_dir = self._resolve_safe_annotation_run_dir(candidate)
            if safe_run_dir is not None:
                run_dir_value = str(safe_run_dir)
                break

        return {
            "input_dir": input_dir_value,
            "output_dir": str(self._coerce_annotation_output_dir(self.output_dir_var.get() or "")),
            "mode": self._normalize_mode_value(),
            "vehicle_model": str(self.vehicle_model_var.get() or "").strip(),
            "vehicle_custom": str(self.vehicle_custom_var.get() or "").strip(),
            "plate_custom": str(self.plate_custom_var.get() or "").strip(),
            "character_model": str(self.character_model_var.get() or "").strip(),
            "character_custom": str(self.character_custom_var.get() or "").strip(),
            "device": self._get_effective_yolo_device_choice(),
            "conf": float(self.conf_var.get()),
            "plate_dataset_run": str(self._resolve_safe_annotation_run_dir(self.plate_dataset_run_var.get()) or ""),
            "plate_dataset_images": str(self.plate_dataset_images_var.get() or "").strip(),
            "plate_train_pct": float(self.plate_train_pct.get()),
            "plate_val_pct": float(self.plate_val_pct.get()),
            "manual_xml_template": bool(self.manual_xml_template_var.get()),
            "manual_vehicle_assist": bool(self.manual_vehicle_assist_var.get()),
            "workflow_route": self._normalize_workflow_route_value(),
            "manual_entry_mode": self._normalize_manual_entry_mode(),
            "auto_vehicle_choice": self._normalize_auto_vehicle_choice(),
            "workflow_step": self._get_workflow_step(),
            "free_mode_screen": self._coerce_free_mode_screen(),
            "manual_review_active": bool(self._manual_review_active),
            "manual_review_from_auto": bool(self._manual_review_from_auto),
            "manual_review_origin_route": self._normalize_workflow_route_value(self._manual_review_origin_route),
            "last_completed_workflow_route": self._normalize_workflow_route_value(self._last_completed_workflow_route),
            "manual_review_export_ready": bool(self._manual_review_export_ready),
            "manual_review_history": list(self._manual_review_history_entries or []),
            "last_preview_run_dir": run_dir_value,
            "last_preview_index": (
                int(self.current_preview_index)
                if self.current_preview_index is not None
                else -1
            ),
            "last_preview_filename": str(getattr(selected_ann, "filename", "") or "").strip(),
            "plate_model_identity": str(dict(getattr(self, "_plate_model_runtime_meta", {}) or {}).get("identity") or "").strip(),
            "plate_model_source": str(dict(getattr(self, "_plate_model_runtime_meta", {}) or {}).get("source") or "").strip(),
            "plate_model_scope": str(dict(getattr(self, "_plate_model_runtime_meta", {}) or {}).get("scope") or "").strip(),
        }

    def _collect_campaign_project_snapshot(self, *, include_preview_approved: bool = True) -> dict:
        selected_ann = self._get_preview_annotation()
        run_dir_value = ""
        for candidate in (
            getattr(self, "current_annotation_run_dir", None),
            getattr(self, "last_staging_run_dir", None),
            str(self.plate_dataset_run_var.get() or "").strip(),
        ):
            safe_run_dir = self._resolve_safe_annotation_run_dir(candidate)
            if safe_run_dir is not None:
                run_dir_value = str(safe_run_dir)
                break

        try:
            from ..campaign_manager import CAMPAIGN
            active_project = CAMPAIGN.get_active_project_name()
            iteration_num = int(CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            active_project = ""
            iteration_num = 1

        payload = {
            "project": str(active_project or "").strip(),
            "iteration": int(iteration_num),
            "input_dir": str(self.input_dir_var.get() or "").strip(),
            "output_dir": str(self._coerce_annotation_output_dir(self.output_dir_var.get() or "")),
            "mode": self._normalize_mode_value(),
            "vehicle_model": str(self.vehicle_model_var.get() or "").strip(),
            "vehicle_custom": str(self.vehicle_custom_var.get() or "").strip(),
            "plate_custom": str(self.plate_custom_var.get() or "").strip(),
            "character_model": str(self.character_model_var.get() or "").strip(),
            "character_custom": str(self.character_custom_var.get() or "").strip(),
            "device": self._get_effective_yolo_device_choice(),
            "conf": float(self.conf_var.get()),
            "plate_dataset_run": str(self._resolve_safe_annotation_run_dir(self.plate_dataset_run_var.get()) or ""),
            "plate_dataset_images": str(self.plate_dataset_images_var.get() or "").strip(),
            "plate_train_pct": float(self.plate_train_pct.get()),
            "plate_val_pct": float(self.plate_val_pct.get()),
            "manual_xml_template": bool(self.manual_xml_template_var.get()),
            "manual_vehicle_assist": bool(self.manual_vehicle_assist_var.get()),
            "workflow_route": self._normalize_workflow_route_value(),
            "manual_entry_mode": self._normalize_manual_entry_mode(),
            "auto_vehicle_choice": self._normalize_auto_vehicle_choice(),
            "workflow_step": self._get_workflow_step(),
            "manual_review_active": bool(self._manual_review_active),
            "manual_review_from_auto": bool(self._manual_review_from_auto),
            "manual_review_origin_route": self._normalize_workflow_route_value(self._manual_review_origin_route),
            "last_completed_workflow_route": self._normalize_workflow_route_value(self._last_completed_workflow_route),
            "manual_review_export_ready": bool(self._manual_review_export_ready),
            "manual_review_history": list(self._manual_review_history_entries or []),
            "last_preview_run_dir": run_dir_value,
            "last_preview_index": (
                int(self.current_preview_index)
                if self.current_preview_index is not None
                else -1
            ),
            "last_preview_filename": str(getattr(selected_ann, "filename", "") or "").strip(),
            "plate_model_identity": str(dict(getattr(self, "_plate_model_runtime_meta", {}) or {}).get("identity") or "").strip(),
            "plate_model_source": str(dict(getattr(self, "_plate_model_runtime_meta", {}) or {}).get("source") or "").strip(),
            "plate_model_scope": str(dict(getattr(self, "_plate_model_runtime_meta", {}) or {}).get("scope") or "").strip(),
            "saved_at": datetime.datetime.now().isoformat(timespec="seconds"),
        }
        if include_preview_approved:
            payload["preview_approved_filenames"] = sorted(self._get_preview_approved_filenames())
        return payload

    def _sanitize_free_mode_session_snapshot(self, session_state: dict | None = None) -> dict:
        defaults = self._annotation_session_defaults()
        state = dict(session_state or {})
        project_root = CONFIG.DIR_9_PROJECTS

        def _sanitize_path_value(key: str, fallback: str = ""):
            raw_value = str(state.get(key) or "").strip()
            if raw_value and self._path_is_within(raw_value, project_root):
                state[key] = fallback
            elif raw_value:
                state[key] = raw_value
            else:
                state[key] = fallback

        _sanitize_path_value("input_dir", defaults["input_dir"])
        _sanitize_path_value("output_dir", defaults["output_dir"])
        _sanitize_path_value("vehicle_custom", "")
        _sanitize_path_value("plate_custom", "")
        _sanitize_path_value("character_custom", "")
        _sanitize_path_value("plate_dataset_run", "")
        _sanitize_path_value("plate_dataset_images", "")
        _sanitize_path_value("last_preview_run_dir", "")

        if not str(state.get("vehicle_custom") or "").strip() and str(state.get("vehicle_model") or "").strip() == "Custom":
            state["vehicle_model"] = defaults["vehicle_model"]

        state["free_mode_screen"] = (
            self._normalize_free_mode_screen_value(state.get("free_mode_screen"))
            or defaults["free_mode_screen"]
        )
        state["manual_review_origin_route"] = self._normalize_workflow_route_value(
            state.get("manual_review_origin_route")
        )

        return state

    def capture_free_mode_snapshot_for_project_return(self):
        try:
            snapshot = self._collect_free_mode_session_snapshot()
        except Exception as e:
            logger.debug(f"Nie udalo sie zapisac migawki free mode przed wejsciem w projekt: {e}")
            return

        self._pre_campaign_free_mode_snapshot = self._sanitize_free_mode_session_snapshot(snapshot)

    def _load_campaign_project_snapshot(self) -> dict:
        snapshot_path = self._get_campaign_annotation_state_path()
        if snapshot_path is None or not snapshot_path.exists():
            return {}

        try:
            loaded = json.loads(snapshot_path.read_text(encoding="utf-8"))
        except Exception:
            return {}

        return loaded if isinstance(loaded, dict) else {}

    def _save_campaign_project_snapshot(self) -> bool:
        return self._save_campaign_project_snapshot_with_options(include_preview_approved=True)

    def _save_campaign_project_snapshot_with_options(self, *, include_preview_approved: bool = True) -> bool:
        snapshot_path = self._get_campaign_annotation_state_path()
        if snapshot_path is None:
            return False

        try:
            payload = self._collect_campaign_project_snapshot(
                include_preview_approved=include_preview_approved,
            )
            if not include_preview_approved:
                existing = self._load_campaign_project_snapshot()
                if "preview_approved_filenames" in existing and "preview_approved_filenames" not in payload:
                    payload["preview_approved_filenames"] = list(existing.get("preview_approved_filenames") or [])
            snapshot_path.parent.mkdir(parents=True, exist_ok=True)
            snapshot_path.write_text(
                json.dumps(payload, ensure_ascii=False, indent=2),
                encoding="utf-8",
            )
            return True
        except Exception as e:
            logger.debug(f"Nie udalo sie zapisac projektowego stanu Z2: {e}")
            return False

    def _cancel_pending_campaign_route_cleanup(self) -> None:
        pending = getattr(self, "_campaign_route_cleanup_after_id", None)
        if pending:
            try:
                self.frame.after_cancel(pending)
            except Exception:
                pass
        self._campaign_route_cleanup_after_id = None
        self._campaign_route_cleanup_token = int(
            getattr(self, "_campaign_route_cleanup_token", 0) or 0
        ) + 1

    def _build_campaign_route_cleanup_payload(
        self,
        *,
        active_project: str,
        candidate_inputs: list[Path],
        explicit_run_dirs: set[str],
        manual_run_keep: set[str],
        remove_persisted_runs: bool,
    ) -> dict:
        try:
            from ..campaign_manager import CAMPAIGN
        except Exception:
            return {}

        search_roots: list[Path] = []
        if bool(remove_persisted_runs):
            for root_candidate in (
                CAMPAIGN.get_staging_dir("auto_ann"),
                CAMPAIGN.get_dir("auto_ann"),
            ):
                if root_candidate is None:
                    continue
                try:
                    search_roots.append(Path(root_candidate))
                except Exception:
                    continue

        stage_root = CAMPAIGN.get_staging_dir("plate_stage")
        try:
            stage_root_path = Path(stage_root) if stage_root is not None else None
        except Exception:
            stage_root_path = None

        try:
            stage_dir = self._get_manual_plate_stage_dir()
        except Exception:
            stage_dir = None

        return {
            "active_project": str(active_project or "").strip(),
            "candidate_inputs": list(candidate_inputs or []),
            "explicit_run_dirs": set(explicit_run_dirs or set()),
            "manual_run_keep": set(manual_run_keep or set()),
            "search_roots": search_roots,
            "stage_root": stage_root_path,
            "stage_dir": stage_dir,
            "remove_persisted_runs": bool(remove_persisted_runs),
        }

    def _schedule_deferred_campaign_route_cleanup(self, payload: dict | None) -> bool:
        if not isinstance(payload, dict) or not bool(payload.get("remove_persisted_runs")):
            return False

        token = int(getattr(self, "_campaign_route_cleanup_token", 0) or 0)
        active_project = str(payload.get("active_project") or "").strip()
        candidate_inputs = list(payload.get("candidate_inputs") or [])
        explicit_run_dirs = set(payload.get("explicit_run_dirs") or set())
        manual_run_keep = set(payload.get("manual_run_keep") or set())
        search_roots = list(payload.get("search_roots") or [])
        stage_root = payload.get("stage_root")
        stage_dir = payload.get("stage_dir")

        def _is_cancelled() -> bool:
            if token != int(getattr(self, "_campaign_route_cleanup_token", 0) or 0):
                return True
            try:
                from ..campaign_manager import CAMPAIGN

                current_project = str(CAMPAIGN.get_active_project_name() or "").strip()
            except Exception:
                current_project = ""
            return bool(active_project and current_project != active_project)

        def _start_worker() -> None:
            if _is_cancelled():
                return
            self._campaign_route_cleanup_after_id = None

            def worker() -> None:
                cleanup_started = time.perf_counter()
                result = {
                    "removed_runs": 0,
                    "removed_stage": False,
                }
                invalidate_roots: list[Path] = []
                visited: set[str] = set()

                if not _is_cancelled():
                    for root in search_roots:
                        if _is_cancelled():
                            return
                        try:
                            if not root.exists() or not root.is_dir():
                                continue
                        except Exception:
                            continue

                        try:
                            run_paths = PROJECT_CACHE.list_annotation_run_dirs(root, require_xml=False)
                        except Exception:
                            continue

                        deleted_any = False
                        for run_dir in run_paths:
                            if _is_cancelled():
                                return
                            try:
                                if not run_dir.is_dir():
                                    continue
                                run_key = str(run_dir.resolve())
                            except Exception:
                                try:
                                    run_key = str(Path(run_dir))
                                except Exception:
                                    continue

                            if run_key in visited:
                                continue
                            visited.add(run_key)

                            manifest = {}
                            remove_run = run_key in explicit_run_dirs
                            if not remove_run:
                                manifest = self._load_annotation_run_manifest(run_dir)
                                manifest_input = str(manifest.get("input_dir") or "").strip()
                                if manifest_input:
                                    remove_run = any(
                                        self._paths_equivalent(manifest_input, candidate_input)
                                        for candidate_input in candidate_inputs
                                    )

                            if not remove_run or not self._path_is_within(run_dir, root):
                                continue

                            if run_key in manual_run_keep or self._annotation_run_manifest_has_manual_value(manifest):
                                continue

                            try:
                                shutil.rmtree(run_dir)
                                result["removed_runs"] += 1
                                deleted_any = True
                            except Exception as e:
                                logger.debug(
                                    f"Nie udalo sie usunac runu po zmianie toru E2 ({run_dir}): {e}"
                                )

                        if deleted_any:
                            invalidate_roots.append(root)

                if (
                    not _is_cancelled()
                    and stage_root is not None
                    and isinstance(stage_dir, Path)
                ):
                    try:
                        if (
                            stage_dir.exists()
                            and self._path_is_within(stage_dir, stage_root)
                        ):
                            shutil.rmtree(stage_dir)
                            result["removed_stage"] = True
                    except Exception as e:
                        logger.debug(f"Nie udalo sie wyczyscic stage po zmianie toru E2: {e}")

                def _finish() -> None:
                    if _is_cancelled():
                        return
                    for root in invalidate_roots:
                        try:
                            PROJECT_CACHE.invalidate_annotation_run_dirs(root)
                        except Exception:
                            continue

                    elapsed_ms = max(0.0, (time.perf_counter() - cleanup_started) * 1000.0)
                    if elapsed_ms >= 20.0 or result["removed_runs"] or result["removed_stage"]:
                        logger.debug(
                            "[AnnotationTab][PERF] deferred_campaign_route_cleanup: "
                            f"{elapsed_ms:.1f} ms | removed_runs={int(result['removed_runs'])} "
                            f"removed_stage={bool(result['removed_stage'])}"
                        )

                self._post_to_ui(_finish)

            try:
                threading.Thread(target=worker, daemon=True).start()
            except Exception as e:
                logger.debug(f"Nie udalo sie uruchomic odroczonego cleanupu toru E2: {e}")

        try:
            self._campaign_route_cleanup_after_id = self.frame.after(180, _start_worker)
        except Exception:
            self._campaign_route_cleanup_after_id = None
            _start_worker()
        return True

    def reset_campaign_iteration_route_state(
        self,
        new_target: str | None = None,
        *,
        remove_persisted_runs: bool = True,
    ) -> dict:
        reset_started = time.perf_counter()
        result = {
            "removed_runs": 0,
            "removed_snapshot": False,
            "removed_stage": False,
        }

        try:
            from ..campaign_manager import CAMPAIGN

            active_project = str(CAMPAIGN.get_active_project_name() or "").strip()
            if not active_project:
                return result

            target = str(new_target or CAMPAIGN.get_iteration_target() or "").strip().lower()
            if target not in {"plate", "char"}:
                target = "plate"

            pending = getattr(self, "_free_mode_session_save_after_id", None)
            if pending:
                try:
                    self.frame.after_cancel(pending)
                except Exception:
                    pass
            self._free_mode_session_save_after_id = None

            candidate_inputs: list[Path] = []
            iteration_raw_dir = CAMPAIGN.get_iteration_raw_dir()
            if iteration_raw_dir is not None:
                candidate_inputs.append(Path(iteration_raw_dir))

            raw_root = CAMPAIGN.get_dir("raw")
            if raw_root is not None:
                iter_num = int(CAMPAIGN.get_current_iteration_num() or 1)
                raw_iter_dir = Path(raw_root) / f"Iteracja_{iter_num:03d}"
                candidate_inputs.append(raw_iter_dir if raw_iter_dir.exists() else Path(raw_root))

            try:
                candidate_inputs.append(self._get_manual_plate_stage_images_dir())
            except Exception:
                pass

            stored_manual_source = {}
            try:
                stored_manual_source = CAMPAIGN.get_last_plate_manual_source()
            except Exception:
                stored_manual_source = {}

            manual_run_keep = set()
            for candidate in (
                str(stored_manual_source.get("source_run_path") or "").strip(),
                str(stored_manual_source.get("source_xml_path") or "").strip(),
            ):
                if not candidate:
                    continue
                try:
                    manual_path = Path(candidate)
                    if manual_path.suffix.lower() == ".xml":
                        manual_path = manual_path.parent
                    manual_run_keep.add(str(manual_path.resolve()))
                except Exception:
                    try:
                        manual_run_keep.add(str(Path(candidate)))
                    except Exception:
                        pass

            explicit_run_dirs = set()
            for candidate in (
                str(CAMPAIGN.get_step2_staging_run() or "").strip(),
                str(getattr(self, "current_annotation_run_dir", "") or "").strip(),
                str(getattr(self, "last_staging_run_dir", "") or "").strip(),
                str(self.plate_dataset_run_var.get() or "").strip(),
            ):
                if not candidate:
                    continue
                try:
                    explicit_run_dirs.add(str(Path(candidate).resolve()))
                except Exception:
                    explicit_run_dirs.add(str(Path(candidate)))

            self._cancel_pending_campaign_route_cleanup()
            cleanup_payload = self._build_campaign_route_cleanup_payload(
                active_project=active_project,
                candidate_inputs=candidate_inputs,
                explicit_run_dirs=explicit_run_dirs,
                manual_run_keep=manual_run_keep,
                remove_persisted_runs=bool(remove_persisted_runs),
            )

            snapshot_path = self._get_campaign_annotation_state_path(active_project)
            try:
                if snapshot_path is not None and snapshot_path.exists():
                    snapshot_path.unlink()
                    result["removed_snapshot"] = True
            except Exception as e:
                logger.debug(f"Nie udalo sie usunac snapshotu Z2 po zmianie toru E2: {e}")

            self._preview_session_restore_index = -1
            self._preview_session_restore_filename = ""
            if raw_root is not None:
                iter_num = int(CAMPAIGN.get_current_iteration_num() or 1)
                input_dir = Path(raw_root) / f"Iteracja_{iter_num:03d}"
                if not input_dir.exists():
                    input_dir = Path(raw_root)
            else:
                input_dir = None

            self._reset_campaign_runtime_state(input_dir=input_dir)
            self._campaign_context_project_name = str(active_project or "").strip()
            try:
                self._refresh_step2_action_states()
            except Exception:
                pass
            if bool(remove_persisted_runs):
                self._schedule_deferred_campaign_route_cleanup(cleanup_payload)
                result["cleanup_deferred"] = True
        except Exception as e:
            logger.debug(f"Nie udalo sie zresetowac stanu iteracji po zmianie toru E2: {e}")

        elapsed_ms = max(0.0, (time.perf_counter() - reset_started) * 1000.0)
        if elapsed_ms >= 20.0:
            logger.debug(
                "[AnnotationTab][PERF] reset_campaign_iteration_route_state: "
                f"{elapsed_ms:.1f} ms | removed_runs={int(result.get('removed_runs', 0) or 0)}, "
                f"removed_stage={bool(result.get('removed_stage'))}, "
                f"removed_snapshot={bool(result.get('removed_snapshot'))} "
                f"cleanup_deferred={1 if bool(result.get('cleanup_deferred')) else 0}"
            )
        return result

    @staticmethod
    def _dir_has_images(path_like) -> bool:
        if not path_like:
            return False

        try:
            return bool(get_image_files(Path(path_like)))
        except Exception:
            return False

    def prepare_campaign_iteration_transition(self, *, input_dir: Path | None = None) -> dict:
        result = {"removed_snapshot": False}

        try:
            from ..campaign_manager import CAMPAIGN

            active_project = str(CAMPAIGN.get_active_project_name() or "").strip()
        except Exception:
            active_project = ""

        pending = getattr(self, "_free_mode_session_save_after_id", None)
        if pending:
            try:
                self.frame.after_cancel(pending)
            except Exception:
                pass
        self._free_mode_session_save_after_id = None

        try:
            if active_project:
                snapshot_path = self._get_campaign_annotation_state_path(active_project)
            else:
                snapshot_path = None
            if snapshot_path is not None and snapshot_path.exists():
                snapshot_path.unlink()
                result["removed_snapshot"] = True
        except Exception as e:
            logger.debug(f"Nie udalo sie usunac snapshotu Z2 przed nowa iteracja: {e}")

        try:
            self._preview_session_restore_index = -1
            self._preview_session_restore_filename = ""
            self._reset_campaign_runtime_state(input_dir=input_dir)
        except Exception as e:
            logger.debug(f"Nie udalo sie wyczyscic runtime Z2 przed nowa iteracja: {e}")

        self._campaign_context_project_name = ""
        try:
            self._refresh_step2_action_states()
        except Exception:
            pass
        return result

    def _get_campaign_iteration_artifact_bundle(
        self,
        *,
        images_dir: Path | None = None,
        iteration_num: int | None = None,
    ) -> dict:
        if self._is_free_mode_session_context():
            return {}
        try:
            from ..campaign_manager import CAMPAIGN

            if not CAMPAIGN.get_active_project_name():
                return {}
            iter_value = int(iteration_num or CAMPAIGN.get_current_iteration_num() or 1)
            preferred_images_dir = images_dir or CAMPAIGN.get_master_pool_dir() or CAMPAIGN.get_iteration_raw_dir(iter_value)
            return dict(
                CAMPAIGN.get_iteration_artifact_bundle(
                    images_dir=preferred_images_dir,
                    iteration_num=iter_value,
                ) or {}
            )
        except Exception:
            return {}

    def _get_campaign_auto_annotation_bootstrap(self, iteration_target: str | None = None) -> dict:
        bootstrap = {
            "input_dir": None,
            "input_source": "raw",
            "manual_template": False,
            "plate_model_path": "",
            "restore_run_dir": None,
        }

        try:
            from ..campaign_manager import CAMPAIGN

            if not CAMPAIGN.get_active_project_name():
                return bootstrap

            target = str(iteration_target or CAMPAIGN.get_iteration_target() or "").strip().lower()
            raw_dir = CAMPAIGN.get_dir("raw")
            if raw_dir is None:
                return bootstrap

            iter_num = int(CAMPAIGN.get_current_iteration_num() or 1)
            raw_root = Path(raw_dir)
            iter_dir = raw_root / f"Iteracja_{iter_num:03d}"
            default_input = iter_dir if iter_dir.exists() else raw_root
            auto_dir = CAMPAIGN.get_dir("auto_ann")
            project_start_mode = str(getattr(CAMPAIGN, "get_project_start_mode", lambda *_a, **_k: "fresh")() or "fresh").strip().lower()

            registry_bundle = self._get_campaign_iteration_artifact_bundle(
                images_dir=CAMPAIGN.get_master_pool_dir() or default_input,
                iteration_num=iter_num,
            )
            registry_plate_source = dict(registry_bundle.get("plate_source") or {})
            registry_plate_model = dict(registry_bundle.get("plate_model") or {})
            registry_image_source = dict(registry_bundle.get("image_source") or {})

            plate_model_path = str(CAMPAIGN.get_global_model("plate") or "").strip()
            registry_plate_model_path = str(registry_plate_model.get("path") or "").strip()
            if not plate_model_path or not Path(plate_model_path).exists():
                plate_model_path = registry_plate_model_path
            plate_model_ready = bool(plate_model_path and Path(plate_model_path).exists())

            bootstrap["input_dir"] = default_input
            bootstrap["plate_model_path"] = plate_model_path if plate_model_ready else ""
            bootstrap["manual_template"] = bool(target == "plate" and not plate_model_ready)

            registry_expected_image_token = str(registry_image_source.get("image_set_token") or "").strip()
            registry_plate_expected_token = str(registry_plate_source.get("expected_image_set_token") or "").strip()
            registry_plate_xml_token = str(registry_plate_source.get("xml_image_set_token") or "").strip()
            registry_plate_image_set_match = registry_plate_source.get("image_set_match")
            if registry_plate_image_set_match is None:
                registry_plate_source_usable = bool(
                    not registry_expected_image_token
                    or not registry_plate_xml_token
                    or registry_expected_image_token == registry_plate_xml_token
                    or (registry_plate_expected_token and registry_plate_expected_token == registry_plate_xml_token)
                )
            else:
                registry_plate_source_usable = bool(registry_plate_image_set_match)

            registry_run_path = str(registry_plate_source.get("run_dir") or "").strip()
            registry_images_path = str(registry_plate_source.get("images_dir") or "").strip()
            if registry_images_path:
                try:
                    registry_images_dir = Path(registry_images_path)
                except Exception:
                    registry_images_dir = None
                if registry_images_dir is not None and self._dir_has_images(registry_images_dir):
                    bootstrap["input_dir"] = registry_images_dir
            if registry_plate_source_usable and registry_run_path and bootstrap.get("restore_run_dir") is None:
                try:
                    registry_run_dir = Path(registry_run_path)
                except Exception:
                    registry_run_dir = None
                if (
                    registry_run_dir is not None
                    and registry_run_dir.exists()
                    and registry_run_dir.is_dir()
                    and (registry_run_dir / "annotations.xml").exists()
                ):
                    bootstrap["restore_run_dir"] = registry_run_dir
                    bootstrap["input_source"] = "registry_plate_source"
                    if target == "plate":
                        bootstrap["manual_template"] = False

            manual_source_run = self._find_reused_manual_source_run(default_input)
            if (
                bootstrap.get("restore_run_dir") is None
                and manual_source_run is not None
                and (manual_source_run / "annotations.xml").exists()
            ):
                bootstrap["restore_run_dir"] = manual_source_run
                bootstrap["input_source"] = "manual_source_run"
                if target == "plate":
                    bootstrap["manual_template"] = False
            elif bootstrap.get("restore_run_dir") is None and iter_num == 1 and project_start_mode == "assets":
                stored_manual_source = CAMPAIGN.get_last_plate_manual_source()
                for raw_candidate in (
                    str(stored_manual_source.get("source_run_path") or "").strip(),
                    str(stored_manual_source.get("source_xml_path") or "").strip(),
                ):
                    if not raw_candidate:
                        continue
                    try:
                        run_candidate = Path(raw_candidate)
                        if run_candidate.suffix.lower() == ".xml":
                            run_candidate = run_candidate.parent
                    except Exception:
                        continue
                    if run_candidate.exists() and run_candidate.is_dir() and (run_candidate / "annotations.xml").exists():
                        bootstrap["restore_run_dir"] = run_candidate
                        bootstrap["input_source"] = "project_imported_manual_source"
                        if target == "plate":
                            bootstrap["manual_template"] = False
                        break

                stored_input_path = str(stored_manual_source.get("source_input_path") or "").strip()
                if stored_input_path and not self._dir_has_images(default_input):
                    try:
                        stored_input_dir = Path(stored_input_path)
                    except Exception:
                        stored_input_dir = None
                    if stored_input_dir is not None and self._dir_has_images(stored_input_dir):
                        bootstrap["input_dir"] = stored_input_dir
                        if bootstrap["input_source"] == "raw":
                            bootstrap["input_source"] = "project_imported_images"

            reuse_source_input = None
            try:
                ingest_manifest = CAMPAIGN.load_ingest_manifest(iter_num)
            except Exception:
                ingest_manifest = {}

            if isinstance(ingest_manifest, dict):
                selection_mode = str(ingest_manifest.get("selection_mode") or "").strip().lower()
                try:
                    reused_from_iteration = int(ingest_manifest.get("reused_from_iteration", 0) or 0)
                except (TypeError, ValueError):
                    reused_from_iteration = 0

                if selection_mode == "iteration_reuse" and reused_from_iteration > 0:
                    reuse_source_input = CAMPAIGN.get_iteration_raw_dir(reused_from_iteration)

                if (
                    bootstrap.get("restore_run_dir") is None
                    and selection_mode in {"pool_reuse", "stage_reuse", "iteration_reuse"}
                    and reused_from_iteration > 0
                ):
                    try:
                        previous_bundle = self._get_campaign_previous_manual_source_bundle()
                    except Exception:
                        previous_bundle = {}

                    previous_run_dir = self._resolve_safe_annotation_run_dir(
                        (previous_bundle or {}).get("run_dir"),
                        require_xml=True,
                    )
                    if previous_run_dir is not None:
                        bootstrap["restore_run_dir"] = previous_run_dir
                        bootstrap["input_source"] = "reused_previous_manual_source"
                        if target == "plate":
                            bootstrap["manual_template"] = False

            if bootstrap.get("restore_run_dir") is None and reuse_source_input is not None and auto_dir is not None:
                reuse_source_input = Path(reuse_source_input)
                manual_reuse_run = self._find_reused_manual_source_run(reuse_source_input)
                if manual_reuse_run is not None and (manual_reuse_run / "annotations.xml").exists():
                    bootstrap["restore_run_dir"] = manual_reuse_run
                    bootstrap["input_source"] = "reused_manual_source_run"
                    if target == "plate":
                        bootstrap["manual_template"] = False
                else:
                    training_source_run = self._find_reused_training_source_run(reuse_source_input)
                    if training_source_run is not None and (training_source_run / "annotations.xml").exists():
                        bootstrap["restore_run_dir"] = training_source_run
                        bootstrap["input_source"] = "reused_training_source_run"
                        if target == "plate":
                            bootstrap["manual_template"] = False
                    else:
                        reuse_run = self._find_latest_annotation_run_for_input(
                            reuse_source_input,
                            [Path(auto_dir)],
                        )
                        if reuse_run is not None and (reuse_run / "annotations.xml").exists():
                            bootstrap["restore_run_dir"] = reuse_run
                            bootstrap["input_source"] = "reused_iteration_run"
                            if target == "plate":
                                bootstrap["manual_template"] = False

            if bootstrap.get("restore_run_dir") is None and auto_dir is not None:
                try:
                    latest_for_input = self._find_latest_annotation_run_for_input(
                        Path(bootstrap.get("input_dir")) if bootstrap.get("input_dir") else None,
                        [Path(auto_dir)],
                    )
                except Exception:
                    latest_for_input = None
                if latest_for_input is not None and (latest_for_input / "annotations.xml").exists():
                    bootstrap["restore_run_dir"] = latest_for_input
                    bootstrap["input_source"] = "latest_approved_run"
                    if target == "plate":
                        bootstrap["manual_template"] = False

            if target != "plate":
                return bootstrap

            if self._dir_has_images(default_input):
                return bootstrap

            current_stage = self._get_manual_plate_stage_images_dir()
            if self._dir_has_images(current_stage):
                bootstrap["input_dir"] = current_stage
                bootstrap["input_source"] = "stage_current_iteration"
                return bootstrap

            if iter_num > 1:
                prev_stage = self._get_manual_plate_stage_dir().parent / f"Iteracja_{iter_num - 1:03d}" / "images"
                if self._dir_has_images(prev_stage):
                    bootstrap["input_dir"] = prev_stage
                    bootstrap["input_source"] = "stage_previous_iteration"
                    return bootstrap

            latest_run = None
            if auto_dir is not None:
                latest_run = self._find_latest_annotation_run_dir(Path(auto_dir))

            if latest_run is None:
                return bootstrap

            manifest = self._load_annotation_run_manifest(latest_run)
            manifest_input = str(manifest.get("input_dir") or "").strip()
            if manifest_input and self._dir_has_images(manifest_input):
                bootstrap["input_dir"] = Path(manifest_input)
                bootstrap["input_source"] = "latest_approved_run"
                bootstrap["restore_run_dir"] = latest_run
                if target == "plate":
                    bootstrap["manual_template"] = False
                return bootstrap

            if (latest_run / "annotations.xml").exists():
                bootstrap["input_source"] = "latest_approved_run"
                bootstrap["restore_run_dir"] = latest_run
                if target == "plate":
                    bootstrap["manual_template"] = False
        except Exception as e:
            logger.debug(f"Nie udalo sie zbudowac bootstrapu Z2 dla kampanii: {e}")

        return bootstrap

    @staticmethod
    def _normalize_campaign_iteration_target_value(target: str | None) -> str:
        value = str(target or "").strip().lower()
        if value in {"plate", "plates", "tablica", "tablice", "pose"}:
            return "plate"
        if value in {"char", "chars", "character", "characters", "znak", "znaki"}:
            return "char"
        return ""

    def _is_campaign_char_repair_return_mode(self) -> bool:
        if self._is_free_mode_session_context():
            return False
        try:
            from ..campaign_manager import CAMPAIGN

            return bool(
                CAMPAIGN.get_active_project_name()
                and int(CAMPAIGN.get_current_step() or 0) == 3
                and str(CAMPAIGN.get_iteration_target() or "").strip().lower() == "char"
                and str(CAMPAIGN.get_step3_status() or "").strip().lower() == "needs_rework"
            )
        except Exception:
            return False

    def _is_campaign_plate_step4_repair_return_mode(self) -> bool:
        if self._is_free_mode_session_context():
            return False
        try:
            from ..campaign_manager import CAMPAIGN

            if not CAMPAIGN.get_active_project_name():
                return False
            if int(CAMPAIGN.get_current_step() or 0) != 4:
                return False
            if str(CAMPAIGN.get_iteration_target() or "").strip().lower() != "plate":
                return False

            approved_stats = dict(CAMPAIGN.get_plate_approved_set_stats() or {})
            approved_images = int(approved_stats.get("images", 0) or 0)
            return approved_images < 2
        except Exception:
            return False

    @staticmethod
    def _campaign_step2_iteration_target_label(target: str) -> str:
        if target == "plate":
            return "tor tablic"
        if target == "char":
            return "tor znaków"
        return "nie wybrano toru"

    def _campaign_step2_route_button_label(
        self,
        route: str,
        *,
        current_target: str = "",
        last_target: str = "",
    ) -> str:
        route = self._normalize_campaign_iteration_target_value(route)
        current_target = self._normalize_campaign_iteration_target_value(current_target)
        last_target = self._normalize_campaign_iteration_target_value(last_target)

        if route == "plate":
            if not current_target and last_target == "plate":
                return "A. Tablice (kontynuuj)"
            return "A. Tablice"

        if route == "char":
            if not current_target and last_target == "char":
                return "B. Znaki (kontynuuj)"
            return "B. Znaki"

        return ""

    def _get_campaign_step2_route_lock_reason(
        self,
        *,
        current_step: int,
        step2_status: str,
        step3_status: str,
        iteration_target: str,
    ) -> str:
        current_target = self._normalize_campaign_iteration_target_value(iteration_target)
        if current_target not in {"plate", "char"}:
            return ""

        active_route_label = self._campaign_step2_route_button_label(current_target)
        if not active_route_label:
            active_route_label = (
                "A. Tablice"
                if current_target == "plate"
                else "B. Znaki"
            )

        if current_step > 2:
            return (
                f"Ta iteracja trwa już w „{active_route_label}”. "
                "Drugi tor będzie dostępny dopiero w nowej iteracji."
            )

        if str(step2_status or "").strip().lower() in {"approved"}:
            return (
                f"Ta iteracja trwa już w „{active_route_label}”. "
                "Drugi tor będzie dostępny dopiero w nowej iteracji."
            )

        return ""

    def _build_campaign_step2_route_choices(
        self,
        *,
        current_step: int,
        step2_status: str,
        step3_status: str,
        iteration_target: str,
        plate_model_ready: bool,
        char_route_source_exists: bool,
    ) -> tuple[str, str, list[Step2RouteChoiceViewModel]]:
        route_hint = (
            "Wybierz tor tej iteracji."
            if not iteration_target
            else f"Wybrany tor: {self._campaign_step2_iteration_target_label(iteration_target)}."
        )
        route_lock_reason = self._get_campaign_step2_route_lock_reason(
            current_step=current_step,
            step2_status=step2_status,
            step3_status=step3_status,
            iteration_target=iteration_target,
        )
        target_locked = bool(route_lock_reason)

        try:
            from ..campaign_manager import CAMPAIGN

            last_target = self._normalize_campaign_iteration_target_value(CAMPAIGN.get_last_iteration_target())
            current_iteration = int(CAMPAIGN.get_current_iteration_num() or 1)
        except Exception:
            last_target = ""
            current_iteration = 1

        char_continue_available = bool(
            current_iteration > 1
            and last_target == "char"
            and int(current_step or 0) == 2
            and str(step2_status or "").strip().lower() == "pending"
            and str(step3_status or "").strip().lower() == "pending"
        )

        route_choices = [
            Step2RouteChoiceViewModel(
                id="plate",
                label=self._campaign_step2_route_button_label(
                    "plate",
                    current_target=iteration_target,
                    last_target=last_target,
                ),
                visible=True,
                enabled=bool(not target_locked and iteration_target != "plate"),
                selected=bool(iteration_target == "plate"),
                command_id="choose_iteration_target",
                command_context={"target": "plate"},
            ),
            Step2RouteChoiceViewModel(
                id="char",
                label=self._campaign_step2_route_button_label(
                    "char",
                    current_target=iteration_target,
                    last_target=last_target,
                ),
                visible=True,
                enabled=bool(
                    not target_locked
                    and iteration_target != "char"
                    and (plate_model_ready or char_route_source_exists or char_continue_available)
                ),
                selected=bool(iteration_target == "char"),
                command_id="choose_iteration_target",
                command_context={"target": "char"},
            ),
        ]
        return route_hint, route_lock_reason, route_choices

    def get_campaign_step2_bootstrap(self, *, iteration_target: str | None = None) -> dict:
        target = self._normalize_campaign_iteration_target_value(iteration_target)
        bootstrap = dict(self._get_campaign_auto_annotation_bootstrap(target) or {})
        restore_run_dir = self._resolve_safe_annotation_run_dir(
            bootstrap.get("restore_run_dir"),
            require_xml=True,
        )
        bootstrap["restore_run_dir"] = restore_run_dir
        bootstrap["input_source"] = str(bootstrap.get("input_source") or "").strip()
        bootstrap["manual_template"] = bool(bootstrap.get("manual_template"))
        bootstrap["plate_model_path"] = str(bootstrap.get("plate_model_path") or "").strip()
        return bootstrap

    def get_campaign_step2_source_state(self, *, iteration_target: str | None = None) -> dict:
        result = {
            "iteration_target": "",
            "ready": False,
            "has_source": False,
            "needs_more_tables": False,
            "images_with_plates": 0,
            "total_plates": 0,
            "restore_run_dir": None,
            "run_name": "",
            "bootstrap": {},
            "input_source": "",
            "manual_template": False,
            "plate_model_ready": False,
        }

        if self._is_free_mode_session_context():
            return result

        try:
            from ..campaign_manager import CAMPAIGN

            if not CAMPAIGN.get_active_project_name():
                return result

            target = self._normalize_campaign_iteration_target_value(
                iteration_target or CAMPAIGN.get_iteration_target()
            )
            if target not in {"plate", "char"}:
                return result

            current_step = int(CAMPAIGN.get_current_step() or 0)
            step2_status = str(CAMPAIGN.get_step2_status() or "").strip().lower()
            current_iteration = int(CAMPAIGN.get_current_iteration_num() or 1)
            last_iteration_target = self._normalize_campaign_iteration_target_value(
                CAMPAIGN.get_last_iteration_target()
            )
            plate_model_path = str(CAMPAIGN.get_global_model("plate") or "").strip()
        except Exception:
            return result

        bootstrap = self.get_campaign_step2_bootstrap(iteration_target=target)
        restore_run_dir = bootstrap.get("restore_run_dir")
        effective_plate_model_path = str(bootstrap.get("plate_model_path") or plate_model_path or "").strip()

        result.update(
            iteration_target=target,
            bootstrap=dict(bootstrap),
            input_source=str(bootstrap.get("input_source") or "").strip(),
            manual_template=bool(bootstrap.get("manual_template")),
            plate_model_ready=bool(effective_plate_model_path and Path(effective_plate_model_path).exists()),
        )

        continuation_char_effective_allowed = False
        if target == "char" and current_iteration > 1 and current_step == 2 and step2_status == "pending":
            try:
                ingest_manifest = CAMPAIGN.load_ingest_manifest(current_iteration)
            except Exception:
                ingest_manifest = {}
            manifest_mode = str((ingest_manifest or {}).get("selection_mode", "") or "").strip().lower()
            continuation_char_effective_allowed = bool(
                last_iteration_target == "char"
                and manifest_mode in {"pool_reuse", "iteration_reuse", "stage_reuse"}
            )

        if target == "char" and (
            current_step >= 3
            or step2_status == "approved"
            or continuation_char_effective_allowed
        ):
            try:
                effective_source = dict(self._build_campaign_char_effective_source() or {})
            except Exception:
                effective_source = {}

            effective_run_dir = self._resolve_existing_run_dir(effective_source.get("run_dir"))
            effective_images_dir = self._resolve_existing_dir(effective_source.get("images_dir"))
            effective_xml_path = self._path_value_to_path(effective_source.get("xml_path"))
            if (
                effective_run_dir is not None
                and effective_images_dir is not None
                and effective_xml_path is not None
                and effective_xml_path.exists()
            ):
                result["has_source"] = True
                result["restore_run_dir"] = effective_run_dir
                result["run_name"] = str(
                    effective_source.get("display_name")
                    or getattr(effective_run_dir, "name", "")
                    or ""
                ).strip()
                result["bootstrap"] = {
                    "restore_run_dir": effective_run_dir,
                    "input_dir": effective_images_dir,
                    "xml_path": effective_xml_path,
                    "input_source": "campaign_char_effective_source",
                    "manual_template": False,
                    "plate_model_path": str(plate_model_path or "").strip(),
                    "display_name": result["run_name"],
                    "run_name": result["run_name"],
                    "contributor_run_dir": str(effective_source.get("contributor_run_dir") or "").strip(),
                }
                result["input_source"] = "campaign_char_effective_source"
                result["manual_template"] = False
                result["images_with_plates"] = int(effective_source.get("images_with_plates", 0) or 0)
                result["total_plates"] = int(effective_source.get("total_plates", 0) or 0)
                if int(result["images_with_plates"] or 0) >= 2 and int(result["total_plates"] or 0) > 0:
                    result["ready"] = True
                elif int(result["total_plates"] or 0) > 0:
                    result["needs_more_tables"] = True
                return result

        if restore_run_dir is None:
            return result

        result["has_source"] = True
        result["restore_run_dir"] = restore_run_dir
        try:
            result["run_name"] = str(Path(restore_run_dir).name or "").strip()
        except Exception:
            result["run_name"] = ""

        try:
            manifest = self._load_annotation_run_manifest(restore_run_dir)
            manual_ready = bool(self._annotation_run_manifest_has_manual_value(manifest))
        except Exception:
            manifest = {}
            manual_ready = False

        try:
            images_with_plates, total_plates = self._get_run_plate_annotation_counts(restore_run_dir)
        except Exception:
            images_with_plates, total_plates = 0, 0
        try:
            approved_images_with_plates, approved_total_plates = self._get_run_plate_approved_counts(restore_run_dir)
        except Exception:
            approved_images_with_plates, approved_total_plates = 0, 0

        result["images_with_plates"] = int(images_with_plates or 0)
        result["total_plates"] = int(total_plates or 0)
        result["approved_images_with_plates"] = int(approved_images_with_plates or 0)
        result["approved_total_plates"] = int(approved_total_plates or 0)

        if target == "plate":
            result["ready"] = True
            return result

        plate_annotations_ready = int(total_plates or 0) > 0
        if not manual_ready and not plate_annotations_ready:
            return result

        result["images_with_plates"] = int(approved_images_with_plates or 0)
        if int(approved_images_with_plates or 0) >= 2 and int(approved_total_plates or 0) > 0:
            result["ready"] = True
        else:
            result["needs_more_tables"] = True

        return result

    def _get_campaign_latest_approved_plate_run_state(self, *, input_dir: Path | None = None) -> dict:
        result = {
            "run_dir": None,
            "run_name": "",
            "images_with_plates": 0,
            "total_plates": 0,
        }

        if self._is_free_mode_session_context():
            return result

        try:
            from ..campaign_manager import CAMPAIGN

            if not CAMPAIGN.get_active_project_name():
                return result

            auto_dir = CAMPAIGN.get_dir("auto_ann")
            if auto_dir is None:
                return result
        except Exception:
            return result

        try:
            auto_root = Path(auto_dir)
        except Exception:
            return result

        approved_run = None
        if input_dir is not None:
            try:
                approved_run = self._find_latest_annotation_run_for_input(input_dir, [auto_root])
            except Exception:
                approved_run = None

        if approved_run is None:
            approved_run = self._find_latest_annotation_run_dir(auto_root)

        approved_run = self._resolve_safe_annotation_run_dir(approved_run, require_xml=True)
        if approved_run is None:
            return result

        try:
            images_with_plates, total_plates = self._get_run_plate_annotation_counts(approved_run)
        except Exception:
            images_with_plates, total_plates = 0, 0

        result.update(
            run_dir=approved_run,
            run_name=str(approved_run.name or "").strip(),
            images_with_plates=int(images_with_plates or 0),
            total_plates=int(total_plates or 0),
        )
        return result

    def get_campaign_step2_view_model(self) -> Step2ViewModel:
        result = Step2ViewModel(
            stage_key="step2",
            iteration_target="",
            current_step=0,
            step2_status="pending",
            state="locked",
            title="E2. Wybierz tor iteracji",
            summary="E2 odblokuje się po zatwierdzeniu paczki wejściowej z E1.",
            details="Najpierw domknij E1.",
            route_hint="Wybierz tor tej iteracji.",
            route_lock_reason="",
            route_choices=[],
            primary_cta=None,
            secondary_cta=None,
        )

        if self._is_free_mode_session_context():
            return result

        try:
            from ..campaign_manager import CAMPAIGN

            if not CAMPAIGN.get_active_project_name():
                return result

            current_step = int(CAMPAIGN.get_current_step() or 0)
            step2_status = str(CAMPAIGN.get_step2_status() or "").strip().lower() or "pending"
            step3_status = str(CAMPAIGN.get_step3_status() or "").strip().lower() or "pending"
            iteration_target = self._normalize_campaign_iteration_target_value(CAMPAIGN.get_iteration_target())
        except Exception:
            return result

        summary = result.summary
        details = result.details
        state = result.state
        primary_cta = None
        secondary_cta = None
        route_hint = result.route_hint
        route_lock_reason = ""
        route_choices: list[Step2RouteChoiceViewModel] = []
        title = result.title

        try:
            plate_model_path = str(CAMPAIGN.get_global_model("plate") or "").strip()
            plate_model_ready = bool(plate_model_path and Path(plate_model_path).exists())
        except Exception:
            plate_model_ready = False
        char_route_source_exists = False
        if (not plate_model_ready) and iteration_target != "char":
            try:
                char_route_source_exists = bool(
                    dict(self.get_campaign_step2_source_state(iteration_target="char") or {}).get("has_source")
                )
            except Exception:
                char_route_source_exists = False

        route_hint, route_lock_reason, route_choices = self._build_campaign_step2_route_choices(
            current_step=current_step,
            step2_status=step2_status,
            step3_status=step3_status,
            iteration_target=iteration_target,
            plate_model_ready=plate_model_ready,
            char_route_source_exists=char_route_source_exists,
        )

        if not iteration_target:
            state = "in_progress" if current_step >= 2 else "locked"
            summary = "Wybierz tor tej iteracji."
            details = (
                "Wybierz tor tej iteracji, bo od tej decyzji zależy dalszy przebieg pracy. "
                "Tor tablic prowadzi od razu do przygotowania danych i treningu modelu tablic. "
                "Tor znaków najpierw korzysta z tablic jako źródła wejściowego, a potem odblokowuje etap pracy nad znakami. "
                "W jednej iteracji pracujesz tylko w jednym torze."
            )
            return Step2ViewModel(
                stage_key="step2",
                iteration_target=iteration_target,
                current_step=current_step,
                step2_status=step2_status,
                state=state,
                title=title,
                summary=summary,
                details=details,
                route_hint=route_hint,
                route_lock_reason=route_lock_reason,
                route_choices=route_choices,
                primary_cta=primary_cta,
                secondary_cta=secondary_cta,
            )

        source_state = self.get_campaign_step2_source_state(iteration_target=iteration_target)
        plate_model_ready = bool(source_state.get("plate_model_ready"))
        title = (
            "E2. Tor tablic i przygotowanie Z2"
            if iteration_target == "plate"
            else "E2. Tor znaków i przygotowanie tablic"
        )

        if iteration_target == "plate":
            bootstrap = dict(source_state.get("bootstrap") or {})
            source_run_name = str(source_state.get("run_name") or "").strip()
            input_dir = bootstrap.get("input_dir")
            approved_state = self._get_campaign_latest_approved_plate_run_state(input_dir=input_dir)
            approved_images = int(approved_state.get("images_with_plates", 0) or 0)
            approved_total = int(approved_state.get("total_plates", 0) or 0)
            project_approved_images = 0
            project_approved_plates = 0
            try:
                from ..campaign_manager import CAMPAIGN
                approved_stats = dict(CAMPAIGN.get_plate_approved_set_stats() or {})
                project_approved_images = int(approved_stats.get("images", 0) or 0)
                project_approved_plates = int(approved_stats.get("plates", 0) or 0)
            except Exception:
                project_approved_images = 0
                project_approved_plates = 0
            project_has_ready_plate_set = bool(
                project_approved_plates > 0
                and project_approved_images >= 2
            )

            if (
                (current_step >= 4 or step2_status == "approved")
                and not project_has_ready_plate_set
                and approved_state.get("run_dir") is not None
                and (approved_total <= 0 or approved_images < 2)
            ):
                state = "needs_attention"
