    def _collect_preview_category_breakdown(self) -> dict[str, int]:
        annotations = list(self.current_annotations or [])
        manual_images = sum(1 for ann in annotations if self._preview_annotation_is_manually_corrected(ann))
        auto_images = sum(
            1
            for ann in annotations
            if getattr(ann, "is_successful", False) and not self._preview_annotation_is_manually_corrected(ann)
        )
        problem_images = max(0, int(len(annotations)) - int(manual_images) - int(auto_images))
        approved_images = sum(1 for ann in annotations if self._preview_annotation_is_explicitly_approved(ann))
        return {
            "total": int(len(annotations)),
            "manual": int(manual_images),
            "auto": int(auto_images),
            "problem": int(problem_images),
            "approved": int(approved_images),
        }

    def _refresh_approval_breakdown_canvas(self):
        box = getattr(self, "approve_breakdown_box", None)
        canvas = getattr(self, "approve_breakdown_canvas", None)
        label = getattr(self, "approve_breakdown_lbl", None)
        if box is None or canvas is None:
            return

        palette = getattr(self.app, "palette", {})
        panel_bg = palette.get("panel", palette.get("bg", "#1f1f1f"))
        panel_border = palette.get("panel_border", palette.get("border", "#3a3a3a"))
        manual_color = palette.get("warning", "#f39c12")
        auto_color = palette.get("success", "#27ae60")
        problem_color = palette.get("error", "#c0392b")
        approved_color = palette.get("accent", "#0e639c")
        fg_color = palette.get("fg", "#f3f3f3")
        muted_color = palette.get("muted", "#c7c7c7")

        try:
            box.configure(bg=panel_bg, highlightbackground=panel_border, highlightcolor=panel_border)
            canvas.configure(bg=panel_bg)
        except Exception:
            pass

        breakdown = self._collect_preview_category_breakdown()
        total = int(breakdown.get("total", 0) or 0)
        manual_images = int(breakdown.get("manual", 0) or 0)
        auto_images = int(breakdown.get("auto", 0) or 0)
        problem_images = int(breakdown.get("problem", 0) or 0)
        approved_images = int(breakdown.get("approved", 0) or 0)

        try:
            width = max(120, int(canvas.winfo_width() or 320))
        except Exception:
            width = 320
        height = 46

        try:
            canvas.delete("all")
        except Exception:
            return

        left = 8
        right = max(left + 1, width - 8)
        bar_width = max(1, right - left)

        if total <= 0:
            try:
                canvas.create_rectangle(left, 10, right, 24, fill=panel_bg, outline=panel_border, width=1)
                canvas.create_text(
                    width / 2,
                    17,
                    text="Brak aktywnej puli obrazów",
                    fill=muted_color,
                    font=("Segoe UI", 8),
                )
            except Exception:
                pass
            if label is not None:
                try:
                    self._set_inline_label_state(
                        label,
                        text="M 0 | A 0 | -- 0 | OK 0",
                        tone="muted",
                        emphasis=False,
                    )
                except Exception:
                    pass
            return

        segments = [
            ("M", manual_images, manual_color),
            ("A", auto_images, auto_color),
            ("--", problem_images, problem_color),
        ]
        cursor = float(left)
        for badge, count, color in segments:
            if count <= 0:
                continue
            segment_width = max(1.0, bar_width * (float(count) / float(total)))
            x1 = cursor
            x2 = right if badge == segments[-1][0] else min(float(right), cursor + segment_width)
            try:
                canvas.create_rectangle(x1, 10, x2, 24, fill=color, outline="")
                if (x2 - x1) >= 24:
                    canvas.create_text(
                        (x1 + x2) / 2,
                        17,
                        text=f"{badge} {count}",
                        fill=("#1b1b1b" if badge == "M" else panel_bg),
                        font=("Segoe UI", 8, "bold"),
                    )
            except Exception:
                pass
            cursor = x2

        try:
            canvas.create_rectangle(left, 10, right, 24, outline=panel_border, width=1)
        except Exception:
            pass

        ok_ratio = max(0.0, min(1.0, float(approved_images) / float(total)))
        ok_right = left + (bar_width * ok_ratio)
        try:
            canvas.create_rectangle(left, 31, right, 38, fill=panel_bg, outline=panel_border, width=1)
            if approved_images > 0:
                canvas.create_rectangle(left, 31, ok_right, 38, fill=approved_color, outline="")
                if ok_right - left >= 32:
                    canvas.create_text(
                        (left + ok_right) / 2,
                        34,
                        text=f"OK {approved_images}",
                        fill=panel_bg,
                        font=("Segoe UI", 7, "bold"),
                    )
        except Exception:
            pass

        if label is not None:
            try:
                self._set_inline_label_state(
                    label,
                    text=f"M {manual_images} | A {auto_images} | -- {problem_images} | OK {approved_images}",
                    tone="muted",
                    emphasis=False,
                )
            except Exception:
                pass

    def _refresh_manual_stage_export_box_style(self):
        box = getattr(self, "manual_stage_export_box", None)
        if box is None:
            return

        palette = getattr(self.app, "palette", {})
        box_bg = palette.get("panel", palette.get("bg", "#1f1f1f"))
        border = palette.get("panel_border", palette.get("border", "#3a3a3a"))
        title_fg = palette.get("muted", "#9a9a9a")
        muted = palette.get("muted_dim", palette.get("muted", "#9a9a9a"))

        try:
            box.configure(bg=box_bg, highlightbackground=border, highlightcolor=border)
        except Exception:
            pass

        for label, color in (
            (getattr(self, "manual_stage_export_title_lbl", None), title_fg),
            (getattr(self, "manual_stage_export_help_lbl", None), muted),
        ):
            if label is None:
                continue
            try:
                label.configure(bg=box_bg, fg=color)
            except Exception:
                pass

    def _set_status_label_state(self, text: str, tone: str = "neutral"):
        if not self._set_inline_label_state(self.status_label, text=text, tone=tone, emphasis=True):
            style_map = {
                "neutral": "PanelStatusNeutral.TLabel",
                "info": "PanelStatusInfo.TLabel",
                "success": "PanelStatusSuccess.TLabel",
                "warning": "PanelStatusWarning.TLabel",
                "error": "PanelStatusError.TLabel",
            }
            self.status_label.config(
                text=text,
                style=style_map.get(str(tone or "").lower(), "PanelStatusNeutral.TLabel")
            )

    def _set_annotation_process_log_visibility(self, visible: bool):
        if not hasattr(self, "annotation_log_overlay"):
            return

        self._annotation_log_visible = bool(visible)
        try:
            self.annotation_log_overlay.place_forget()
        except Exception:
            pass

        if self._annotation_log_visible:
            try:
                if hasattr(self.app, "show_global_terminal"):
                    self.app.show_global_terminal()
            except Exception:
                pass

        if hasattr(self, "btn_toggle_annotation_log"):
            try:
                self.btn_toggle_annotation_log.configure(text="Terminal")
            except Exception:
                pass
        return

        if self._annotation_log_visible:
            try:
                self.annotation_log_overlay.place(
                    relx=0.015,
                    rely=0.02,
                    relwidth=0.97,
                    relheight=0.96,
                )
                self.annotation_log_overlay.lift()
            except Exception:
                pass
            try:
                self.annotation_log_overlay.update_idletasks()
                self.annotation_log_frame.update_idletasks()
                self.annotation_log_host.update_idletasks()
            except Exception:
                pass
            if hasattr(self, "btn_toggle_annotation_log"):
                self.btn_toggle_annotation_log.configure(text="Ukryj terminal")
        else:
            try:
                self.annotation_log_overlay.place_forget()
            except Exception:
                pass
            if hasattr(self, "btn_toggle_annotation_log"):
                self.btn_toggle_annotation_log.configure(text="Pokaż terminal")

    def _toggle_annotation_process_log(self):
        try:
            if hasattr(self.app, "toggle_global_terminal"):
                self.app.toggle_global_terminal()
                return
        except Exception:
            pass
        self._set_annotation_process_log_visibility(
            not getattr(self, "_annotation_log_visible", False)
        )

    def _validate_models(self):
        mode = self._normalize_mode_value()
        if self._mode_uses_vehicle(mode):
            if self.vehicle_model_var.get() == "Custom":
                p = self.vehicle_custom_var.get()
                if not p or not Path(p).exists(): raise ValueError("Nie znaleziono własnego modelu pojazdów!")
                if not validate_model_file(Path(p))[0]: raise ValueError("Model pojazdów jest uszkodzony!")
        
        if self._mode_uses_plate(mode):
            p = (self.plate_custom_var.get() or "").strip()
            if not p or not Path(p).exists(): raise ValueError("Wskaż wytrenowany model tablic (.pt)!")
            if not validate_model_file(Path(p))[0]: raise ValueError("Model tablic jest uszkodzony!")

    def _validate_vehicle_model_selection(self):
        if self.vehicle_model_var.get() == "Custom":
            p = (self.vehicle_custom_var.get() or "").strip()
            if not p or not Path(p).exists():
                raise ValueError("Nie znaleziono wlasnego modelu pojazdow!")
            if not validate_model_file(Path(p))[0]:
                raise ValueError("Model pojazdow jest uszkodzony!")

    def ensure_campaign_context_ready_for_active_project(self, *, force: bool = False) -> bool:
        if bool(getattr(self, "_campaign_project_restore_in_progress", False)):
            return False

        try:
            from ..campaign_manager import CAMPAIGN
            active_project = str(CAMPAIGN.get_active_project_name() or "").strip()
        except Exception:
            active_project = ""

        if not active_project:
            self._campaign_context_project_name = ""
            return False

        if self._is_free_mode_session_context():
            return False

        current_project = str(getattr(self, "_campaign_context_project_name", "") or "").strip()
        if not force and current_project == active_project:
            return False

        return bool(self.restore_campaign_context_from_project())

    def ensure_free_mode_session_preview_ready(self, *, force: bool = False) -> bool:
        if not self._is_free_mode_session_context():
            return False
        if getattr(self, "is_processing", False):
            return False

        if bool(getattr(self, "current_annotations", None)) and not force:
            return True

        restored_from_fallback = False
        try:
            has_saved_run = (
                self._resolve_safe_annotation_run_dir(getattr(self, "last_staging_run_dir", None), require_xml=True) is not None
                or self._resolve_safe_annotation_run_dir(str(self.plate_dataset_run_var.get() or "").strip(), require_xml=True) is not None
            )
        except Exception:
            has_saved_run = False

        if not has_saved_run and not force:
            try:
                latest_free_run = self._find_latest_annotation_run_dir(self._get_annotation_output_base_dir())
            except Exception:
                latest_free_run = None
            latest_free_run = self._resolve_safe_annotation_run_dir(latest_free_run, require_xml=True)
            if latest_free_run is None:
                return False
            try:
                self.last_staging_run_dir = latest_free_run
                self.plate_dataset_run_var.set(str(latest_free_run))
                restored_from_fallback = True
            except Exception:
                pass

        try:
            restored = bool(self._restore_preview_from_session_run())
        except Exception as e:
            logger.debug(f"Nie udalo sie przywrocic podgladu Z2 z sesji free mode: {e}")
            return False

        if restored:
            try:
                if not self._get_workflow_route():
                    manifest = self._load_annotation_run_manifest(getattr(self, "current_annotation_run_dir", None))
                    manual_template_like = bool(self._annotation_run_manifest_is_manual_template(manifest))
                    if manual_template_like:
                        self.workflow_route_var.set("manual")
                        self.free_mode_screen_var.set("manual_review")
                        self._manual_review_active = True
                        self._manual_review_from_auto = False
                        self._manual_review_origin_route = "manual"
                        self._last_completed_workflow_route = "manual"
                else:
                    self.workflow_route_var.set("auto")
                    self.free_mode_screen_var.set("auto_summary")
                    self._manual_review_active = False
                    self._manual_review_from_auto = False
                    self._manual_review_origin_route = ""
                    self._last_completed_workflow_route = "auto"
                try:
                    if self._get_z2_thematic_route() == "auto":
                        self._restore_plate_model_selection_from_active_run()
                except Exception:
                    pass
                self._repair_restored_z2_workflow_completion_state()
                self._refresh_step2_action_states()
                self._refresh_free_mode_workflow_ui()
                self._update_preview_edit_status("Przywrócono ostatni run anotacji Z2 z poprzedniej sesji.")
                if restored_from_fallback:
                    self._queue_free_mode_session_save()
            except Exception:
                pass

        return restored

    def clear_campaign_context(self):
        """
        Przywraca neutralny stan zakĹ‚adki Autoanotacji po wyjĹ›ciu z projektu
        i czyĹ›ci wszystkie artefakty poprzedniego projektu z UI.
        """
        try:
            self._hide_campaign_step2_splash()
        except Exception:
            pass
        self._set_campaign_paths_lock_state(False)

        try:
            self.project_paths_info_var.set("")
        except Exception:
            pass

        try:
            self.project_paths_rel_var.set("")
        except Exception:
            pass

        self.current_annotations = []
        self._clear_preview_editor_state(clear_dirty=True)
        self.is_processing = False

        try:
            self.current_input_dir = Path(self.input_dir_var.get().strip())
        except Exception:
            self.current_input_dir = None

        try:
            self.preview_listbox.delete(0, tk.END)
        except Exception:
            pass

        try:
            self.preview_canvas.delete("all")
        except Exception:
            pass

        try:
            self.log_text.delete("1.0", tk.END)
        except Exception:
            pass

        try:
            self.progress.configure(value=0)
        except Exception:
            pass

        try:
            self._set_status_label_state("Gotowy do uruchomienia", "neutral")
        except Exception:
            pass

        try:
            self._set_post_annotation_hint("")
        except Exception:
            pass

        try:
            self._set_progress_counters(0, 0, 0)
        except Exception:
            pass

        try:
            self.start_btn.config(state=tk.NORMAL)
        except Exception:
            pass

        try:
            self.stop_btn.config(state=tk.DISABLED)
        except Exception:
            pass

        try:
            self.approve_btn.config(state=tk.DISABLED)
        except Exception:
            pass

        try:
            self._set_annotation_process_log_visibility(False)
        except Exception:
            pass

        try:
            snapshot = getattr(self, "_pre_campaign_free_mode_snapshot", None)
            self._pre_campaign_free_mode_snapshot = None
            self._apply_free_mode_session_snapshot(
                session_state=snapshot,
                restore_preview=bool(snapshot is None),
            )
            if snapshot is not None:
                try:
                    self.flush_free_mode_session_state()
                except Exception:
                    pass
        except Exception as e:
            logger.debug(f"Nie udalo sie przywrocic ostatniego stanu Z2 po wyjsciu z projektu: {e}")

    def _format_project_relative_path(self, path_value: str) -> str:
        try:
            from ..campaign_manager import CAMPAIGN
            root = CAMPAIGN.get_active_project_root_dir()
            p = Path(path_value)

            if root is not None:
                try:
                    return str(p.relative_to(root))
                except Exception:
                    pass

            return str(p)
        except Exception:
            return str(path_value)

    def _set_campaign_paths_lock_state(self, locked: bool):
        self._campaign_paths_locked = bool(locked)

        try:
            self.input_dir_entry.configure(state=("readonly" if locked else "normal"))
        except Exception:
            pass

        try:
            self.input_dir_browse_btn.configure(state=(tk.DISABLED if locked else tk.NORMAL))
        except Exception:
            pass

        if locked:
            try:
                self.input_dir_entry.selection_clear()
            except Exception:
                pass

        if locked:
            self.project_paths_info_var.set(
                "Ścieżki zostały uzupełnione automatycznie z aktywnego projektu."
            )
            self.project_paths_rel_var.set(
                f"IN:  {self._format_project_relative_path(self.input_dir_var.get().strip())}\n"
                f"OUT: {self._format_project_relative_path(self.output_dir_var.get().strip())}"
            )
        else:
            self.project_paths_info_var.set("")
            self.project_paths_rel_var.set("")

    def _show_campaign_step2_splash(
        self,
        *,
        title: str = "Przygotowuję Z2",
        body: str = "",
        tone: str = "info",
        progress: float | None = None,
    ) -> int:
        overlay = getattr(self, "_campaign_step2_splash_overlay", None)
        card = getattr(self, "_campaign_step2_splash_card", None)
        title_lbl = getattr(self, "_campaign_step2_splash_title_lbl", None)
        body_lbl = getattr(self, "_campaign_step2_splash_body_lbl", None)
        progress = getattr(self, "_campaign_step2_splash_progress", None)
        if overlay is None or card is None or title_lbl is None or body_lbl is None or progress is None:
            return 0

        palette = getattr(self.app, "palette", {})
        panel_bg = palette.get("panel", "#252526")
        fg = palette.get("fg", "#f3f3f3")
        tone_key = str(tone or "info").strip().lower()
        if tone_key == "success":
            accent = palette.get("success", "#2ecc71")
        elif tone_key == "error":
            accent = palette.get("error", "#e74c3c")
        else:
            accent = palette.get("accent", "#4f8de3")

        overlay_bg = blend_hex_colors(panel_bg, "#000000", 0.24)
        card_bg = blend_hex_colors(panel_bg, accent, 0.10)
        border_color = blend_hex_colors(accent, palette.get("panel_border", palette.get("border", "#3c3c3c")), 0.48)

        try:
            overlay.configure(bg=overlay_bg, highlightbackground=overlay_bg, highlightcolor=overlay_bg)
            card.configure(bg=card_bg, highlightbackground=border_color, highlightcolor=border_color)
            title_lbl.configure(text=str(title or "").strip(), bg=card_bg, fg=accent)
            body_lbl.configure(text=str(body or "").strip(), bg=card_bg, fg=fg)
            if hasattr(self.app, "ensure_adaptive_wrap"):
                self.app.ensure_adaptive_wrap(body_lbl, container=card, padding=44, min_wrap=240)
        except Exception:
            pass

        try:
            progress.stop()
            progress.configure(
                mode="determinate",
                maximum=100.0,
                value=(0.0 if progress is None else max(0.0, min(100.0, float(progress)))),
            )
        except Exception:
            pass
        try:
            overlay.place(in_=self.frame, relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0)
            overlay.lift()
        except Exception:
            pass
        was_visible = bool(getattr(self, "_campaign_step2_splash_visible", False))
        self._campaign_step2_splash_visible = True
        if not was_visible:
            self._campaign_step2_splash_token = int(getattr(self, "_campaign_step2_splash_token", 0) or 0) + 1
        try:
            self.frame.update_idletasks()
        except Exception:
            pass
        return int(self._campaign_step2_splash_token)

    def _hide_campaign_step2_splash(self, *, token: int | None = None) -> None:
        current_token = int(getattr(self, "_campaign_step2_splash_token", 0) or 0)
        if token is not None and int(token or 0) != current_token:
            return

        overlay = getattr(self, "_campaign_step2_splash_overlay", None)
        progress = getattr(self, "_campaign_step2_splash_progress", None)
        try:
            if progress is not None:
                progress.stop()
        except Exception:
            pass
        try:
            if overlay is not None:
                overlay.place_forget()
        except Exception:
            pass
        self._campaign_step2_splash_visible = False

    def _begin_campaign_step2_transition(self) -> None:
        self._campaign_step2_transition_in_progress = True
        self._campaign_step2_transition_refresh_pending = False
        self._campaign_step2_transition_skip_heavy_finalize = False

    def _end_campaign_step2_transition(self) -> None:
        self._campaign_step2_transition_in_progress = False
        if not bool(getattr(self, "_campaign_step2_transition_refresh_pending", False)):
            self._campaign_step2_transition_skip_heavy_finalize = False
            return

        self._campaign_step2_transition_refresh_pending = False
        skip_heavy_finalize = bool(getattr(self, "_campaign_step2_transition_skip_heavy_finalize", False))
        self._campaign_step2_transition_skip_heavy_finalize = False
        try:
            self._refresh_left_panel_route_copy()
        except Exception:
            pass
        try:
            self._refresh_detection_configuration_ui()
        except Exception:
            pass
        try:
            self._refresh_step2_action_states()
        except Exception:
            pass
        try:
            self._refresh_free_mode_workflow_ui()
        except Exception:
            pass
        if skip_heavy_finalize:
            try:
                self._sync_right_panel_scrollregion()
            except Exception:
                pass
            return
        try:
            self._refresh_step2_action_states()
        except Exception:
            pass
        try:
            self._refresh_preview_list_summary()
        except Exception:
            pass
        try:
            self._sync_right_panel_scrollregion()
        except Exception:
            pass

